-- Daily challenges for 2026-11-11: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-11-11. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('keeping-your-cool-with-technology', 'Keeping Your Cool with Technology', 'For anyone whose phone, computer or printer can ruin a good mood. Each day is one small way to stay calm when tech misbehaves, set things up so they frustrate you less, and ask for help without feeling foolish.', 'Stress', 365, array['Stress', 'Emotion Regulation', 'Self-Compassion']::text[], 1, '2026-11-11T17:00:00+00:00'::timestamptz),
  ('saying-goodbye-well', 'Saying Goodbye Well', 'For anyone facing an ending, from a move or a new job to a friend leaving town or a season of life closing. Each day is one small way to mark what mattered, say thank you and step toward what comes next.', 'Transitions', 365, array['Life Transitions', 'Relationships']::text[], 1, '2026-11-11T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('keeping-your-cool-with-technology', 'saying-goodbye-well');

